//! Bit-exact parity with Go's lib/shape (fixture: tests/fixtures/go-unit/shapes.txt,
//! generated by goref/base-parity/shapes via `scripts/gen-goref.sh`).
#![allow(non_snake_case)]
extern crate orthoflow_shape as shape;
use geo::{BoxRef, Point, PointRef, Segment};
use shape::*;

fn h(f: f64) -> String {
    format!("{:016x}", f.to_bits())
}
fn pt(p: &Point) -> String {
    format!("{},{}", h(p.X), h(p.Y))
}
fn bx(b: Option<&BoxRef>) -> String {
    match b {
        None => "nil".into(),
        Some(b) => {
            let b = b.get();
            format!("{},{},{}", pt(&b.TL().get()), h(b.Width), h(b.Height))
        }
    }
}
fn q(s: &str) -> String {
    format!("\"{}\"", s.replace('\\', "\\\\").replace('"', "\\\""))
}

const TYPES: &[&str] = &[
    "Square", "RealSquare", "Parallelogram", "Document", "Cylinder", "Queue", "Page", "Package", "Step", "Callout", "StoredData", "Person",
    "C4Person", "Diamond", "Oval", "Circle", "Hexagon", "Cloud", "Table", "Class", "Text", "Code", "Image", "", "weird",
];
const BOXES: &[[f64; 4]] = &[
    [0.0, 0.0, 100.0, 100.0],
    [10.0, 20.0, 200.0, 80.0],
    [-50.5, 33.25, 40.0, 30.0],
    [7.0, 9.0, 25.0, 300.0],
    [100.0, 100.0, 150.0, 61.0],
    [3.3, 4.4, 59.0, 47.0],
    [0.0, 0.0, 1.0, 1.0],
    [12.0, 34.0, 834.0, 523.0],
    [5.0, 5.0, 333.3, 111.1],
    [-200.0, -100.0, 61.044, 20.0],
];

fn np(x: f64, y: f64) -> PointRef {
    geo::NewPoint(x, y)
}

#[test]
fn shape_parity() {
    let dir = std::fs::canonicalize(env!("CARGO_MANIFEST_DIR")).unwrap();
    let want = std::fs::read_to_string(dir.join("../../tests/fixtures/go-unit/shapes.txt")).expect("fixture");
    let mut out: Vec<String> = Vec::new();
    for t in TYPES {
        for (bi, b) in BOXES.iter().enumerate() {
            let box_ = geo::NewBox(np(b[0], b[1]), b[2], b[3]);
            let s = NewShape(t, box_);
            out.push(format!("shape {} {}", q(t), bi));
            out.push(format!("meta {} {} {} {} {}", s.IsRectangular(), s.AspectRatio1(), q(&s.GetType()), s.Is(""), s.Is(t)));
            out.push(format!("box {}", bx(Some(&s.GetBox()))));
            out.push(format!("inner {}", bx(Some(&s.GetInnerBox()))));
            let (px, py) = s.GetDefaultPadding();
            out.push(format!("pad {} {}", h(px), h(py)));
            for a in [[10.0, 10.0, 0.0, 0.0], [50.0, 20.0, 40.0, 40.0], [20.0, 50.0, 10.0, 30.0], [0.5, 300.0, 3.0, 7.0], [123.4, 56.7, 40.0, 20.0]] {
                let p = s.GetInsidePlacement(a[0], a[1], a[2], a[3]);
                let (dw, dh) = s.GetDimensionsToFit(a[0], a[1], a[2], a[3]);
                out.push(format!("place {} dims {} {} content {}", pt(&p), h(dw), h(dh), bx(s.GetInnerBoxForContent(a[0], a[1]).as_ref())));
            }
            let per = s.Perimeter();
            out.push(format!("perimeter {}", per.len()));
            let (cx, cy) = (b[0] + b[2] / 2.0, b[1] + b[3] / 2.0);
            let segs = [
                Segment::new(np(cx, cy), np(cx, b[1] - 50.0)),
                Segment::new(np(cx, cy), np(b[0] + b[2] + 50.0, cy)),
                Segment::new(np(b[0] - 10.0, b[1] - 10.0), np(b[0] + b[2] + 10.0, b[1] + b[3] + 10.0)),
                Segment::new(np(cx + 3.7, cy + 2.1), np(b[0] - 30.0, b[1] + b[3] * 0.8)),
            ];
            for (i, ps) in per.iter().enumerate() {
                for (j, sg) in segs.iter().enumerate() {
                    let pts = ps.Intersections(sg);
                    let strs: Vec<String> = pts.iter().map(|p| pt(&p.get())).collect();
                    out.push(format!("isect {} {} [{}]", i, j, strs.join(";")));
                }
            }
            let trace = [
                [cx, b[1], cx, b[1] - 40.0],
                [b[0], cy, b[0] - 30.0, cy],
                [b[0] + b[2], b[1] + b[3] * 0.3, b[0] + b[2] + 20.0, b[1] + b[3] * 0.3],
                [b[0] + b[2] * 0.25, b[1] + b[3], b[0] + b[2] * 0.25, b[1] + b[3] + 30.0],
                [b[0] + b[2] * 0.1, b[1], b[0] - 10.0, b[1] - 33.0],
            ];
            for tr in trace {
                let rp = np(tr[0], tr[1]);
                let pp = np(tr[2], tr[3]);
                let r = TraceToShapeBorder(&*s, &rp, &pp);
                out.push(format!("trace {} rect {}", pt(&r.get()), pt(&rp.get())));
            }
            out.push(format!("svg {}", q(&s.GetSVGPathData().join("|"))));
            match GetPathCommands(&*s) {
                None => out.push("cmds nil".into()),
                Some(cmds) => {
                    for path in cmds {
                        let parts: Vec<String> = path
                            .iter()
                            .map(|c| format!("{}:{}:{}:{}", c.Kind.0, pt(&c.Control1), pt(&c.Control2), pt(&c.End)))
                            .collect();
                        out.push(format!("cmds {}", parts.join(" ")));
                    }
                }
            }
            if *t == "Cloud" {
                for ar in [0.5, 1.0, 1.25, 3.0] {
                    s.SetInnerBoxAspectRatio(ar);
                    out.push(format!("cloudar {}", bx(Some(&s.GetInnerBox()))));
                }
            }
        }
    }
    for a in [[10.0, 10.0, 1.5], [100.0, 10.0, 3.0], [10.0, 100.0, 1.5], [33.0, 7.0, 2.0]] {
        let (x, y) = LimitAR(a[0], a[1], a[2]);
        out.push(format!("limitar {} {}", h(x), h(y)));
    }
    let want: Vec<&str> = want.lines().collect();
    assert_eq!(out.len(), want.len(), "line count");
    let mut fails = 0;
    for (i, (g, w)) in out.iter().zip(want.iter()).enumerate() {
        if g != w {
            if fails < 10 {
                eprintln!("line {}:\n  want {}\n  got  {}", i + 1, w, g);
            }
            fails += 1;
        }
    }
    assert_eq!(fails, 0, "{} mismatching lines", fails);
}
